public AVector selectClone(int... inds) {
    Vector v = Vector.createLength(inds.length);
    double[] tdata = v.getArray();
    for (int i = 0; i < inds.length; i++) {
        int ix = inds[i];
        checkIndex(ix);  // Check if ix is a valid index
        tdata[i] = unsafeGet(ix);
    }
